package br.com.mvdelivery.app;
import br.com.mvdelivery.model.*;import br.com.mvdelivery.repository.*;import java.time.*;import java.math.*;
public class SmokeTest {public static void main(String[] args)throws Exception{Repository r=new MemoryRepository();Cliente c=new Cliente();c.nome="Ana Souza";c.telefone="31999990001";c.endereco="Rua A";r.save(Schema.CLIENTE,c);Entregador e=new Entregador();e.nome="João";e.contato="31999990002";e.placaMoto="ABC1D23";e.disponivel=true;r.save(Schema.ENTREGADOR,e);Pedido p=new Pedido();p.cliente=c;p.dataPedido=LocalDateTime.now();p.valor=new BigDecimal("25.00");p.status=StatusPedido.PENDENTE;p.enderecoEntrega="Rua B";r.save(Schema.PEDIDO,p);p.entregador=e;p.status=StatusPedido.EM_ROTA;r.save(Schema.PEDIDO,p);p.status=StatusPedido.ENTREGUE;r.save(Schema.PEDIDO,p);if(r.list(Schema.HISTORICO).size()!=3)throw new AssertionError("Histórico");Feedback f=new Feedback();f.pedido=p;f.nota=5;f.dataHora=LocalDateTime.now();r.save(Schema.FEEDBACK,f);Feedback duplicate=new Feedback();duplicate.pedido=p;duplicate.nota=4;duplicate.dataHora=LocalDateTime.now();try{r.save(Schema.FEEDBACK,duplicate);throw new AssertionError("Duplicidade");}catch(IllegalArgumentException ok){}try{r.delete(Schema.CLIENTE,c.idCliente);throw new AssertionError("Vínculo");}catch(IllegalArgumentException ok){}r.delete(Schema.PEDIDO,p.idPedido);if(!r.list(Schema.HISTORICO).isEmpty()||!r.list(Schema.FEEDBACK).isEmpty())throw new AssertionError("Dependências");System.out.println("OK: cadastro, atribuição, status, histórico, feedback único, vínculo e exclusão dependente.");}}
